import pytest
from candidate import car_race_collision

def test_car_race_collision_square_positive_int():
    assert car_race_collision(5) == 25

def test_car_race_collision_zero():
    assert car_race_collision(0) == 0

def test_car_race_collision_negative_value():
    assert car_race_collision(-3) == 9

def test_car_race_collision_large_int():
    n = 10**6
    assert car_race_collision(n) == n**2

def test_car_race_collision_float_input():
    assert car_race_collision(3.5) == 12.25

def test_car_race_collision_bool_input():
    assert car_race_collision(True) == 1

def test_car_race_collision_complex_input():
    c = 2 + 3j
    assert car_race_collision(c) == c**2

def test_car_race_collision_none_raises():
    with pytest.raises(TypeError):
        car_race_collision(None)

def test_car_race_collision_string_raises():
    with pytest.raises(TypeError):
        car_race_collision("5")

def test_car_race_collision_list_raises():
    with pytest.raises(TypeError):
        car_race_collision([1, 2, 3])

def test_car_race_collision_return_type_matches_input():
    assert isinstance(car_race_collision(7), int)
    assert isinstance(car_race_collision(4.2), float)
    assert isinstance(car_race_collision(1+0j), complex)

def test_car_race_collision_purity():
    result1 = car_race_collision(8)
    result2 = car_race_collision(8)
    assert result1 == result2 == 64
